package com.uop.recordingtools.command;

import com.uop.recordingtools.UopRecordingToolsPlugin;
import com.uop.recordingtools.util.*;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import java.util.*;

public final class UopCommand implements CommandExecutor, TabCompleter {
    private final UopRecordingToolsPlugin p;
    private final List<String> roots = List.of("armor","checkpoint","damage","disenchant","enchant","freeze","unfreeze","inv","help","name","permission","protect","reload","reset","version");
    private static final List<String> ARMOR_MATERIALS = List.of("leather","chainmail","iron","gold","diamond","netherite");
    private static final List<String> ARMOR_MODES = List.of("plain","enchanted","max");
    private static final List<String> WEAPONS = List.of("sword","mace","axe","bow","crossbow","trident","pickaxe","shovel","hoe");
    private static final List<String> ENCHANT_SCOPES = List.of("all","armor","equipment","mainhand","offhand","inventory","hand");
    private static final List<String> SLOTS = List.of("helmet","chestplate","leggings","boots","head","chest","legs","feet");
    public UopCommand(UopRecordingToolsPlugin p){this.p=p;}
    private boolean admin(CommandSender s){return s instanceof ConsoleCommandSender || (s instanceof Player x && x.isOp());}
    private boolean allow(CommandSender s,String perm){return admin(s)||s.hasPermission(perm)||(s instanceof Player x&&p.permissions().has(x,perm));}
    private void msg(CommandSender s,String m){s.sendMessage(ChatColor.translateAlternateColorCodes('&',"&7[&bUOP&7] "+m));}
    @Override public boolean onCommand(CommandSender s,Command c,String l,String[] a){try{return run(s,a);}catch(Exception e){msg(s,"&cCommand error: "+e.getMessage());p.getLogger().warning("/uop error: "+e);return true;}}
    private boolean run(CommandSender s,String[] a){if(!admin(s)&&s instanceof Player x&&!p.permissions().has(x,"uop.use")){msg(s,"&cYou do not have permission to use UOP Recording Tools.");return true;}if(a.length==0){help(s);return true;}switch(a[0].toLowerCase(Locale.ROOT)){case "help"->help(s);case "version"->msg(s,"&fUOP Recording Tools &b"+p.getDescription().getVersion()+" &7for Paper 1.21.11");case "reload"->{if(!admin(s)){msg(s,"&cOP/console only.");break;}p.reloadPlugin();msg(s,"&aReloaded.");}case "reset"->reset(s,a);case "armor"->armor(s,a);case "checkpoint"->checkpoint(s,a);case "damage"->damage(s,a);case "enchant"->ench(s,a,false);case "disenchant"->ench(s,a,true);case "freeze"->freeze(s,a,false);case "unfreeze"->freeze(s,a,true);case "inv"->inv(s,a);case "name"->name(s,a);case "protect"->protect(s,a);case "permission"->permission(s,a);default->msg(s,"&cUnknown command. Use /uop help.");}return true;}
    private void need(CommandSender s,String perm){if(!allow(s,perm))throw new IllegalStateException("You do not have permission: "+perm);}
    private void help(CommandSender s){msg(s,"&f/uop armor &7| checkpoint | damage | enchant | disenchant | freeze | unfreeze");msg(s,"&f/uop inv &7| name | protect | permission | reload | reset | version");}
    private void reset(CommandSender s,String[] a){if(!admin(s)){msg(s,"&cOP/console only.");return;}if(a.length>1&&!a[1].equalsIgnoreCase("all"))throw new IllegalArgumentException("Use /uop reset all");p.store().data().set("damage",null);p.store().data().set("freeze",null);p.store().data().set("checkpoints",null);p.store().data().set("loadouts",null);p.store().data().set("tags",null);p.store().data().set("names",null);p.store().data().set("protection",null);p.store().data().set("permissions",null);p.store().data().set("inventories",null);p.store().saveNow();for(Player x:Bukkit.getOnlinePlayers()){p.freeze().unfreeze(x);p.names().refresh(x);}msg(s,"&aAll UOP persistent state reset.");}
    private List<Player> targets(CommandSender s,String token){List<Player> ps=Targets.players(s,token);if(ps.isEmpty())throw new IllegalArgumentException("No matching players: "+token);return ps;}
    private String mode(String[] a,int index){if(a.length<=index)throw new IllegalArgumentException("Mode required.");if(a[index].equalsIgnoreCase("enchanted")){if(a.length<=index+1)throw new IllegalArgumentException("Enchanted mode requires a level 1-10.");return "enchanted "+a[index+1];}return a[index];}
    private void armor(CommandSender s,String[] a){need(s,"uop.armor");if(a.length<2){msg(s,"&f/uop armor set|save|list|delete|give|weapon");return;}switch(a[1].toLowerCase()){case "set"->armorSet(s,a);case "save"->{if(a.length<4)throw new IllegalArgumentException("/uop armor save <set_name> <player>");Player q=Targets.one(s,a[3]);if(q==null)throw new IllegalArgumentException("Player not found");p.armor().saveLoadout(a[2],q);msg(s,"&aSaved loadout "+a[2]);}case "list"->msg(s,"&fLoadouts: &7"+String.join(", ",p.armor().loadouts()));case "delete"->{if(a.length<3)throw new IllegalArgumentException("Name required");p.armor().delete(a[2]);msg(s,"&aDeleted.");}case "give"->armorGive(s,a);case "weapon"->weapon(s,a);default->throw new IllegalArgumentException("Unknown armor action.");}}
    private void armorSet(CommandSender s,String[] a){if(a.length<5)throw new IllegalArgumentException("/uop armor set <targets> <material> <mode> [true|false] [weapons...]");String m=mode(a,4);int next=a[4].equalsIgnoreCase("enchanted")?6:5;List<Player> ps=targets(s,a[2]);boolean weapons=a.length>next?bool(a[next]):false;List<String> ws=a.length>next+1?Arrays.asList(a).subList(next+1,a.length):List.of();for(Player q:ps)p.armor().set(q,a[3],m,weapons,ws);msg(s,"&aArmor set applied to "+ps.size()+" player(s).");}
    private void armorGive(CommandSender s,String[] a){if(a.length<4)throw new IllegalArgumentException("/uop armor give <targets> direct|saved ...");List<Player> ps=targets(s,a[2]);if(a[3].equalsIgnoreCase("saved")){if(a.length<5)throw new IllegalArgumentException("Loadout name required");if(a.length>5)throw new IllegalArgumentException("Too many arguments.");for(Player q:ps)if(!p.armor().giveSaved(a[4],q))throw new IllegalArgumentException("Loadout not found: "+a[4]);}else{if(!a[3].equalsIgnoreCase("direct")||a.length<6)throw new IllegalArgumentException("Direct requires material and mode");String m=mode(a,5);int next=a[5].equalsIgnoreCase("enchanted")?7:6;boolean weapons=a.length>next?bool(a[next]):false;List<String> ws=a.length>next+1?Arrays.asList(a).subList(next+1,a.length):List.of();for(Player q:ps)p.armor().set(q,a[4],m,weapons,ws);}msg(s,"&aLoadout applied.");}
    private void weapon(CommandSender s,String[] a){if(a.length<5||!a[2].equalsIgnoreCase("set"))throw new IllegalArgumentException("/uop armor weapon set <targets> <mode> <weapons...>");String m=mode(a,4);int next=a[4].equalsIgnoreCase("enchanted")?6:5;List<String> ws=Arrays.asList(a).subList(next,a.length);if(ws.isEmpty())throw new IllegalArgumentException("At least one weapon/tool required.");int lvl=Items.level(m,m);for(Player q:targets(s,a[3]))p.armor().giveWeapons(q,ws,m,lvl);}
    private void checkpoint(CommandSender s,String[] a){need(s,"uop.checkpoint");if(a.length<2)throw new IllegalArgumentException("Action required");switch(a[1].toLowerCase()){case "save"->{if(a.length<3)throw new IllegalArgumentException("Name required");if(a.length>4)throw new IllegalArgumentException("Too many arguments.");List<Player> ps=a.length>3?targets(s,a[3]):List.of();var result=p.checkpoints().save(a[2],ps);if(!result.success())throw new IllegalArgumentException(result.error());msg(s,"&aCheckpoint saved for "+result.playerCount()+" player(s).");}case "tp"->{if(a.length!=3)throw new IllegalArgumentException("/uop checkpoint tp <name>");var result=p.checkpoints().tp(a[2]);if(!result.found())throw new IllegalArgumentException("Checkpoint not found.");msg(s,"&aCheckpoint restored: "+result.teleportedPlayers()+" player(s).");}case "list"->{if(a.length!=2)throw new IllegalArgumentException("/uop checkpoint list");msg(s,"&fCheckpoints: &7"+String.join(", ",p.checkpoints().list()));}case "delete"->{if(a.length!=3)throw new IllegalArgumentException("Name required");if(!p.checkpoints().delete(a[2]))throw new IllegalArgumentException("Checkpoint not found.");}case "clear"->{if(a.length>3||a.length==3&&!a[2].equalsIgnoreCase("all"))throw new IllegalArgumentException("Use clear all");p.checkpoints().clear();}default->throw new IllegalArgumentException("Unknown checkpoint action.");}}
    private double num(String x){try{double v=Double.parseDouble(x);if(Double.isNaN(v)||Double.isInfinite(v))throw new IllegalArgumentException("Invalid number: "+x);return v;}catch(NumberFormatException e){throw new IllegalArgumentException("Invalid number: "+x);}}
    private void damage(CommandSender s,String[] a){need(s,"uop.damage");if(a.length<2)throw new IllegalArgumentException("Action required");switch(a[1].toLowerCase()){case "global"->{if(a.length!=3)throw new IllegalArgumentException("/uop damage global <multiplier>");p.damage().global(num(a[2]));}case "outgoing","incoming"->{if(a.length!=4)throw new IllegalArgumentException("/uop damage "+a[1]+" <player> <multiplier>");Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");if(a[1].equalsIgnoreCase("outgoing"))p.damage().outgoing(q,num(a[3]));else p.damage().incoming(q,num(a[3]));}case "set","pair"->{if(a.length!=5)throw new IllegalArgumentException("/uop damage pair <attacker> <victim> <multiplier>");Player x=Targets.one(s,a[2]),y=Targets.one(s,a[3]);if(x==null||y==null)throw new IllegalArgumentException("Players not found");p.damage().pair(x,y,num(a[4]));}case "reset"->damageReset(s,a);default->throw new IllegalArgumentException("Unknown damage action.");}msg(s,"&aDamage rule updated.");}
    private void damageReset(CommandSender s,String[] a){if(a.length<3)throw new IllegalArgumentException("Reset type required.");String t=a[2].toLowerCase(Locale.ROOT);if(t.equals("global")){if(a.length!=3)throw new IllegalArgumentException("/uop damage reset global");p.damage().reset("global",null,null);return;}if(t.equals("all")){if(a.length!=3)throw new IllegalArgumentException("/uop damage reset all");p.damage().resetAll();return;}if(!Set.of("outgoing","incoming","pair").contains(t))throw new IllegalArgumentException("Unknown damage reset type: "+t);int required=t.equals("pair")?5:4;if(a.length!=required)throw new IllegalArgumentException("Incomplete damage reset command.");Player x=Targets.one(s,a[3]);if(x==null)throw new IllegalArgumentException("Player not found");if(t.equals("pair")){Player y=Targets.one(s,a[4]);if(y==null)throw new IllegalArgumentException("Player not found");p.damage().reset("pair",x,y);}else p.damage().reset(t,x,null);}
    private void require(String[] a,int n){if(a.length<n)throw new IllegalArgumentException("Incomplete command arguments.");}
    private void ench(CommandSender s,String[] a,boolean remove){need(s,remove?"uop.disenchant":"uop.enchant");if(a.length<4)throw new IllegalArgumentException("Invalid syntax");String scope=a[1].toLowerCase(Locale.ROOT);if(!ENCHANT_SCOPES.contains(scope))throw new IllegalArgumentException("Invalid enchantment scope: "+scope);List<Player> ps=targets(s,a[2]);String slot=null;String enchName;int level=1;boolean slotScope=scope.equals("armor")||scope.equals("hand");if(remove){if(slotScope){if(a.length!=5)throw new IllegalArgumentException("Expected <scope> <targets> <slot> <enchantment>.");slot=a[3];enchName=a[4];}else{if(a.length!=4)throw new IllegalArgumentException("Expected <scope> <targets> <enchantment>.");enchName=a[3];}}else{if(slotScope&&a.length>=5&&!isInteger(a[4])){if(a.length>6)throw new IllegalArgumentException("Too many arguments.");slot=a[3];enchName=a[4];level=a.length>5?parseLevel(a[5]):1;}else{if(a.length>5)throw new IllegalArgumentException("Too many arguments.");enchName=a[3];if(a.length>4)level=parseLevel(a[4]);}}Enchantment e=Items.enchantment(enchName);if(e==null)throw new IllegalArgumentException("Unknown enchantment: "+enchName);for(Player q:ps)if(remove)p.enchant().remove(q,scope,e,slot);else p.enchant().apply(q,scope,e,level,slot);msg(s,"&aDone for "+ps.size()+" player(s).");}
    private boolean isInteger(String value){try{Integer.parseInt(value);return true;}catch(Exception e){return false;}}
    private int parseLevel(String value){try{int level=Integer.parseInt(value);if(level<1||level>255)throw new IllegalArgumentException("Enchantment level must be 1-255.");return level;}catch(NumberFormatException e){throw new IllegalArgumentException("Invalid enchantment level: "+value);}}
    private void freeze(CommandSender s,String[] a,boolean unfreeze){need(s,"uop.freeze");if(a.length<2)throw new IllegalArgumentException("Targets required");String mode="normal",target=a[1];if(!unfreeze&&(a[1].equalsIgnoreCase("normal")||a[1].equalsIgnoreCase("full"))){mode=a[1];if(a.length<3)throw new IllegalArgumentException("Targets required");target=a[2];}if(a.length>3)throw new IllegalArgumentException("Too many arguments.");List<Player> ps=targets(s,target);for(Player q:ps){if(unfreeze)p.freeze().unfreeze(q);else p.freeze().freeze(q,mode);}msg(s,"&aFreeze state updated for "+ps.size()+" player(s).");}
    private void inv(CommandSender s,String[] a){need(s,"uop.inv");if(a.length<2)throw new IllegalArgumentException("Action required");switch(a[1].toLowerCase()){case "view"->{if(a.length!=3)throw new IllegalArgumentException("/uop inv view <player>");Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");if(!(s instanceof Player))throw new IllegalArgumentException("Only a player can view an inventory.");((Player)s).openInventory(q.getInventory());}case "set"->{if(a.length<5||a.length>6)throw new IllegalArgumentException("/uop inv set <player> <slot> <item> [amount]");Player q=Targets.one(s,a[2]);Material m=Material.matchMaterial(a[4]);if(q==null||m==null||m.isAir())throw new IllegalArgumentException("Invalid target/item");int n=a.length>5?numInt(a[5]):1;p.inventory().set(q,numInt(a[3]),new ItemStack(m,n));}case "remove"->{if(a.length!=4)throw new IllegalArgumentException("/uop inv remove <player> <slot>");Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");p.inventory().remove(q,numInt(a[3]));}case "give","take"->{if(a.length<4||a.length>5)throw new IllegalArgumentException("/uop inv "+a[1]+" <player> <item> [amount]");Player q=Targets.one(s,a[2]);Material m=Material.matchMaterial(a[3]);if(q==null||m==null||m.isAir())throw new IllegalArgumentException("Invalid target/item");int n=a.length>4?numInt(a[4]):1;if(a[1].equalsIgnoreCase("give"))p.inventory().give(q,m,n);else p.inventory().take(q,m,n);}case "swap"->{if(a.length!=6)throw new IllegalArgumentException("/uop inv swap <player> <slot> <player> <slot>");Player x=Targets.one(s,a[2]),y=Targets.one(s,a[4]);if(x==null||y==null)throw new IllegalArgumentException("Player not found");p.inventory().swap(x,numInt(a[3]),y,numInt(a[5]));}case "clear"->{if(a.length!=3)throw new IllegalArgumentException("/uop inv clear <player>");Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");p.inventory().clear(q);}case "backup","restore","backups","backup-delete","back"->{String action=a[1].toLowerCase(Locale.ROOT);if(a.length<3)throw new IllegalArgumentException("Player required.");Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");if(action.equals("backups")){if(a.length!=3)throw new IllegalArgumentException("Usage: /uop inv backups <player>");msg(s,"&fBackups: &7"+String.join(", ",p.inventory().backups(q)));}else{if(a.length!=4)throw new IllegalArgumentException("Backup/history name required.");if(action.equals("backup"))p.inventory().backup(q,a[3]);else if(action.equals("restore")){if(!p.inventory().restore(q,a[3]))throw new IllegalArgumentException("Backup not found: "+a[3]);}else if(action.equals("backup-delete"))p.inventory().backupDelete(q,a[3]);else if(action.equals("back")){if(!p.inventory().back(q,a[3]))throw new IllegalArgumentException("No history available.");}}}case "record"->{if(a.length<3||a.length>4)throw new IllegalArgumentException("Use record start|stop|status [targets].");if(a[2].equalsIgnoreCase("status")){if(a.length!=3)throw new IllegalArgumentException("Usage: /uop inv record status");msg(s,"&fRecording players: &7"+p.inventory().recording().size());break;}if(a.length!=4)throw new IllegalArgumentException("Targets required.");for(Player q:targets(s,a[3])){if(a[2].equalsIgnoreCase("stop"))p.inventory().stopRecord(List.of(q));else if(a[2].equalsIgnoreCase("start"))p.inventory().startRecord(List.of(q));else throw new IllegalArgumentException("Use record start|stop|status.");}}case "lock","unlock"->{if(a.length!=3)throw new IllegalArgumentException("/uop inv "+a[1]+" <player>");Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");p.inventory().lock(q,a[1].equalsIgnoreCase("lock"));}default->throw new IllegalArgumentException("Unknown inventory action.");}msg(s,"&aInventory operation complete.");}
    private int numInt(String x){try{return Integer.parseInt(x);}catch(Exception e){throw new IllegalArgumentException("Invalid integer: "+x);}}
    private boolean bool(String value){if("true".equalsIgnoreCase(value))return true;if("false".equalsIgnoreCase(value))return false;throw new IllegalArgumentException("Expected true or false: "+value);}
    private void name(CommandSender s,String[] a){need(s,"uop.name");if(a.length<2)throw new IllegalArgumentException("Action required");switch(a[1].toLowerCase()){case "hide","show"->{if(a.length!=3)throw new IllegalArgumentException("Target required.");for(Player q:targets(s,a[2]))if(a[1].equalsIgnoreCase("hide"))p.names().hide(q);else p.names().show(q);}case "tag"->tag(s,a);default->throw new IllegalArgumentException("Unknown name action.");}msg(s,"&aName operation complete.");}
    private void tag(CommandSender s,String[] a){if(a.length<3||a[2].equalsIgnoreCase("help")){msg(s,"&f/uop name tag create|edit|list|give|change|remove|delete");return;}switch(a[2].toLowerCase()){case "create","edit"->{if(a.length<8)throw new IllegalArgumentException("create/edit <id> <color> <bold> <italic> <text>");String text=String.join(" ",Arrays.asList(a).subList(7,a.length));boolean bold=bool(a[5]),italic=bool(a[6]);if(a[2].equalsIgnoreCase("create"))p.names().create(a[3],a[4],bold,italic,text);else p.names().edit(a[3],a[4],bold,italic,text);}case "list"->{if(a.length!=3)throw new IllegalArgumentException("/uop name tag list");msg(s,"&fTags: &7"+String.join(", ",p.names().tags()));}case "give","change"->{if(a.length!=5)throw new IllegalArgumentException("/uop name tag "+a[2]+" <targets> <tag>");for(Player q:targets(s,a[3]))p.names().give(q,a[4]);}case "remove"->{if(a.length!=4)throw new IllegalArgumentException("Target required.");for(Player q:targets(s,a[3]))p.names().removeTag(q);}case "delete"->{if(a.length!=4)throw new IllegalArgumentException("Tag id required.");p.names().deleteTag(a[3]);}default->throw new IllegalArgumentException("Unknown tag action.");}}
    private void protect(CommandSender s,String[] a){need(s,"uop.protect");if(a.length<2)throw new IllegalArgumentException("Action required");switch(a[1].toLowerCase()){case "add","uuid","ip","both"->{if(a.length!=3)throw new IllegalArgumentException("Target required.");for(Player q:targets(s,a[2]))p.protection().add(q,a[1].equalsIgnoreCase("add")?"both":a[1]);}case "remove"->{if(a.length!=3)throw new IllegalArgumentException("Target required.");for(Player q:targets(s,a[2]))p.protection().remove(q);}case "list"->{if(a.length!=2)throw new IllegalArgumentException("/uop protect list");msg(s,"&fProtected names: &7"+String.join(", ",p.protection().list()));}case "reset"->{if(a.length!=2)throw new IllegalArgumentException("/uop protect reset");p.protection().reset();}default->throw new IllegalArgumentException("Unknown protection action.");}msg(s,"&aProtection updated.");}
    private void permission(CommandSender s,String[] a){if(!admin(s))throw new IllegalStateException("Permission administration is restricted to actual OPs/server console.");if(a.length<2)throw new IllegalArgumentException("grant|revoke|list|check|reset");switch(a[1].toLowerCase()){case "grant","revoke"->{require(a,4);Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");String[] nodes=Arrays.copyOfRange(a,3,a.length);if(a[1].equalsIgnoreCase("grant"))p.permissions().grant(q,nodes);else p.permissions().revoke(q,nodes);}case "list"->{if(a.length!=3)throw new IllegalArgumentException("/uop permission list <player>");Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");msg(s,"&fPermissions for "+q.getName()+": &7"+String.join(", ",p.permissions().list(q)));}case "check"->{if(a.length!=4)throw new IllegalArgumentException("/uop permission check <player> <node>");Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");msg(s,"&f"+q.getName()+": "+p.permissions().has(q,a[3]));}case "reset"->{if(a.length>4)throw new IllegalArgumentException("Too many arguments.");if(a[2].equalsIgnoreCase("all")){if(a.length!=3)throw new IllegalArgumentException("/uop permission reset all");p.store().data().set("permissions",null);p.store().saveNow();}else{Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");p.permissions().reset(q,a.length>3?a[3]:null);}}default->throw new IllegalArgumentException("Unknown permission action.");}msg(s,"&aPermission operation complete.");}
    @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] a){if(a.length==0)return roots;String prefix=a[a.length-1].toLowerCase(Locale.ROOT);List<String> out=new ArrayList<>();String root=a[0].toLowerCase(Locale.ROOT);if(a.length==1)return filter(roots,prefix);switch(root){case "armor"->armorTab(a,out);case "checkpoint"->checkpointTab(a,out);case "damage"->damageTab(a,out);case "enchant","disenchant"->enchantTab(a,out);case "freeze"->freezeTab(a,out);case "unfreeze"->{if(a.length==2)players(out);}case "inv"->invTab(a,out);case "name"->nameTab(a,out);case "protect"->protectTab(a,out);case "permission"->permissionTab(a,out);}return filter(out,prefix);}
    private List<String> filter(List<String> values,String prefix){return values.stream().filter(x->x.toLowerCase(Locale.ROOT).startsWith(prefix)).distinct().sorted().toList();}
    private void checkpointTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("save","tp","list","delete","clear"));else if(a.length==3&&Set.of("tp","delete").contains(a[1].toLowerCase(Locale.ROOT))){}else if(a.length==4&&a[1].equalsIgnoreCase("save"))players(o);}
    private void damageTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("global","outgoing","incoming","set","pair","reset"));else if(a[1].equalsIgnoreCase("outgoing")||a[1].equalsIgnoreCase("incoming")){if(a.length==3)players(o);}else if(a[1].equalsIgnoreCase("set")||a[1].equalsIgnoreCase("pair")){if(a.length==3||a.length==4)players(o);}else if(a[1].equalsIgnoreCase("reset")){if(a.length==3)o.addAll(List.of("global","outgoing","incoming","pair","all"));else if(a.length==4&&!Set.of("global","all").contains(a[2].toLowerCase(Locale.ROOT)))players(o);else if(a.length==5&&a[2].equalsIgnoreCase("pair"))players(o);}}
    private void enchantTab(String[] a,List<String> o){if(a.length==2)o.addAll(ENCHANT_SCOPES);else if(a.length==3)players(o);else if(a.length==4){for(Enchantment e:Enchantment.values())o.add(e.getKey().getKey());}else if(a.length==5&&!a[1].equalsIgnoreCase("disenchant"))for(int i=1;i<=255;i++)o.add(String.valueOf(i));}
    private void freezeTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("normal","full","all"));else if(a.length==3&&(a[1].equalsIgnoreCase("normal")||a[1].equalsIgnoreCase("full")))players(o);}
    private void invTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("view","set","remove","give","take","swap","clear","backup","restore","backups","backup-delete","record","back","lock","unlock"));else if(a.length==3){String x=a[1].toLowerCase(Locale.ROOT);if(!x.equals("record"))players(o);else o.addAll(List.of("start","stop","status"));}else if(a.length==4){String x=a[1].toLowerCase(Locale.ROOT);if(x.equals("set")||x.equals("remove")||x.equals("swap"))for(int i=0;i<=40;i++)o.add(String.valueOf(i));else if(Set.of("give","take","set").contains(x))for(Material m:Material.values())if(m.isItem()&&!m.isAir())o.add(m.name().toLowerCase(Locale.ROOT));else if(Set.of("backup","restore","backups","backup-delete","back").contains(x)){}else if((x.equals("record"))&&(a[2].equalsIgnoreCase("start")||a[2].equalsIgnoreCase("stop")))players(o);}else if(a.length==5&&a[1].equalsIgnoreCase("swap"))for(int i=0;i<=40;i++)o.add(String.valueOf(i));}
    private void nameTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("hide","show","tag"));else if(a.length==3&&(a[1].equalsIgnoreCase("hide")||a[1].equalsIgnoreCase("show")))players(o);else if(a.length==3&&a[1].equalsIgnoreCase("tag"))o.addAll(List.of("create","edit","list","give","change","remove","delete"));else if(a.length==4&&Set.of("give","change","remove").contains(a[2].toLowerCase(Locale.ROOT)))players(o);else if(a.length==5&&Set.of("give","change").contains(a[2].toLowerCase(Locale.ROOT))){} }
    private void protectTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("add","uuid","ip","both","remove","list","reset"));else if(a.length==3&&Set.of("add","uuid","ip","both","remove").contains(a[1].toLowerCase(Locale.ROOT)))players(o);}
    private void permissionTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("grant","revoke","list","check","reset"));else if(a.length==3&&Set.of("grant","revoke","list","check").contains(a[1].toLowerCase(Locale.ROOT)))players(o);else if(a.length==4&&(a[1].equalsIgnoreCase("grant")||a[1].equalsIgnoreCase("revoke")||a[1].equalsIgnoreCase("check")))o.addAll(List.of("uop.use","uop.armor","uop.checkpoint","uop.damage","uop.enchant","uop.disenchant","uop.freeze","uop.inv","uop.name","uop.protect","*").stream().toList());}
    private void armorTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("set","save","list","delete","give","weapon"));else if(a.length==3){if(a[1].equalsIgnoreCase("set")||a[1].equalsIgnoreCase("give")||a[1].equalsIgnoreCase("weapon"))players(o);}else if(a[1].equalsIgnoreCase("set")){if(a.length==4)o.addAll(ARMOR_MATERIALS);else if(a.length==5)o.addAll(ARMOR_MODES);else if(a.length==6&&a[4].equalsIgnoreCase("enchanted"))for(int i=1;i<=10;i++)o.add(String.valueOf(i));else if(a.length==6)o.addAll(List.of("true","false"));else if(a.length==7&&a[4].equalsIgnoreCase("enchanted"))o.addAll(List.of("true","false"));else if(a.length>=6)o.addAll(WEAPONS);}else if(a[1].equalsIgnoreCase("give")){if(a.length==4)o.addAll(List.of("direct","saved"));else if(a.length==5&&a[3].equalsIgnoreCase("direct"))o.addAll(ARMOR_MATERIALS);else if(a.length==6&&a[3].equalsIgnoreCase("direct"))o.addAll(ARMOR_MODES);else if(a.length==7&&a[5].equalsIgnoreCase("enchanted"))for(int i=1;i<=10;i++)o.add(String.valueOf(i));else if(a.length==7&&a[3].equalsIgnoreCase("direct"))o.addAll(List.of("true","false"));else if(a.length==8&&a[5].equalsIgnoreCase("enchanted"))o.addAll(List.of("true","false"));else if(a.length>=7)o.addAll(WEAPONS);}else if(a[1].equalsIgnoreCase("weapon")){if(a.length==3){}else if(a.length==4)o.add("set");else if(a.length==5)o.addAll(ARMOR_MODES);else if(a.length==6&&a[4].equalsIgnoreCase("enchanted"))for(int i=1;i<=10;i++)o.add(String.valueOf(i));else if(a.length>=6)o.addAll(WEAPONS);}}
    private void players(List<String> o){o.addAll(Bukkit.getOnlinePlayers().stream().map(Player::getName).toList());o.addAll(List.of("@a","@p","@r","@s"));}
}
